#pragma once

#include <d3d11.h>
#include <d3dcompiler.h>
#include <string>
#include <unordered_map>
#include <vector>
#include <wrl/client.h>

// Native LeanCRT renderer: runs the raster permutation of LeanCRT with plain
// D3D11. The shader source is untouched; the HLSL is generated by ReShade fxc
// in spec-constant mode (see native/LeanCRT.hlsl).
class NativeLeanCRT
{
public:
    bool Initialize(ID3D11Device* device, ID3D11DeviceContext* context, const std::wstring& hlslPath, std::wstring& error);
    void Render(ID3D11ShaderResourceView* input, ID3D11RenderTargetView* output, UINT outputWidth, UINT outputHeight);
    void Shutdown();
    bool IsReady() const { return m_ready; }

private:
    struct Texture
    {
        Microsoft::WRL::ComPtr<ID3D11Texture2D>           tex;
        Microsoft::WRL::ComPtr<ID3D11ShaderResourceView>  srv;
        Microsoft::WRL::ComPtr<ID3D11RenderTargetView>    rtv;
        UINT w = 0;
        UINT h = 0;
    };

    struct Pass
    {
        const char* name;
        const char* vs;
        const char* ps;
        int         rt;
        int         rt1;
        bool        clear;
    };

    struct Bindings
    {
        std::vector<UINT> srvs;
        std::vector<UINT> samplers;
        bool              cbuffer = false;
    };

    Microsoft::WRL::ComPtr<ID3D11VertexShader>  GetVS(const char* entry, std::wstring& error);
    Microsoft::WRL::ComPtr<ID3D11PixelShader>   GetPS(const char* entry, std::wstring& error);
    Bindings Reflect(ID3DBlob* blob);
    Texture  CreateTexture(UINT w, UINT h, DXGI_FORMAT format, UINT bind);
    void     BindGraphics(const Bindings& bindings, bool pixel);
    void     RunMaskPrewarm();

    Microsoft::WRL::ComPtr<ID3D11Device>        m_device;
    Microsoft::WRL::ComPtr<ID3D11DeviceContext> m_context;
    std::string                                  m_source;
    std::wstring                                 m_error;

    Texture m_textures[22];
    Microsoft::WRL::ComPtr<ID3D11SamplerState> m_sampler_clamp;
    Microsoft::WRL::ComPtr<ID3D11SamplerState> m_sampler_wrap_v;
    Microsoft::WRL::ComPtr<ID3D11SamplerState> m_sampler_border;
    Microsoft::WRL::ComPtr<ID3D11RasterizerState> m_rasterizer;
    Microsoft::WRL::ComPtr<ID3D11Buffer>       m_frame_cb;
    Microsoft::WRL::ComPtr<ID3D11PixelShader>  m_blit_ps;

    std::unordered_map<std::string, Microsoft::WRL::ComPtr<ID3D11VertexShader>> m_vs;
    std::unordered_map<std::string, Microsoft::WRL::ComPtr<ID3D11PixelShader>>  m_ps;
    std::unordered_map<std::string, Bindings>                                   m_vs_bind;
    std::unordered_map<std::string, Bindings>                                   m_ps_bind;

    UINT m_frame = 60;
    bool m_ready = false;
};
